#include <bits/stdc++.h>
using namespace std;

// Rank of every suffix of text (prefix doubling with a sort per round).
vector<int> suffixRanks(const string &text) {
    int size = text.size();
    vector<int> order(size), rank(size), next(size);
    iota(order.begin(), order.end(), 0);
    for (int i = 0; i < size; i++) rank[i] = (unsigned char)text[i];
    for (int width = 1; width < size; width *= 2) {
        auto key = [&](int i) { return make_pair(rank[i], i + width < size ? rank[i + width] : -1); };
        sort(order.begin(), order.end(), [&](int a, int b) { return key(a) < key(b); });
        int classes = 0;
        for (int j = 0; j < size; j++) {
            if (j > 0 && key(order[j]) != key(order[j - 1])) classes++;
            next[order[j]] = classes;
        }
        rank.swap(next);
        if (classes == size - 1) break;
    }
    return rank;
}

int main() {
    string a, b;
    cin >> a >> b;
    int length = a.size(), m = b.size();
    if (m < length) { puts("-1"); return 0; }
    // Sliding window over b: mismatches = letters whose counts differ from a.
    int difference[26] = {0};
    for (char ch : a) difference[ch - 'a']++;
    for (int i = 0; i < length; i++) difference[b[i] - 'a']--;
    int mismatches = 0;
    for (int v : difference) mismatches += v != 0;
    vector<char> valid(m - length + 1);
    bool any = false;
    for (int start = 0; start <= m - length; start++) {
        valid[start] = mismatches == 0;
        any |= valid[start];
        if (start + length < m) {
            for (auto [idx, delta] : {make_pair(b[start] - 'a', 1), make_pair(b[start + length] - 'a', -1)}) {
                mismatches -= difference[idx] != 0;
                difference[idx] += delta;
                mismatches += difference[idx] != 0;
            }
        }
    }
    if (!any) { puts("-1"); return 0; }
    // Equal-length windows compare like their suffixes: take the valid start with the highest suffix rank.
    vector<int> rank = suffixRanks(b);
    int best = -1;
    for (int start = 0; start <= m - length; start++)
        if (valid[start] && (best < 0 || rank[start] > rank[best])) best = start;
    puts(b.substr(best, length).c_str());
}

import java.io.*;
import java.util.*;

public class Main {
    // Rank of every suffix of text (prefix doubling with a sort per round).
    static int[] suffixRanks(String text) {
        int size = text.length();
        int[] rank = new int[size], next = new int[size];
        for (int i = 0; i < size; i++) rank[i] = text.charAt(i);
        long[] packed = new long[size];
        for (int width = 1; width < size; width *= 2) {
            // Pack (rank[i], rank[i+width] or -1, i) into one long so a primitive sort orders by the pair.
            for (int i = 0; i < size; i++) {
                long second = i + width < size ? rank[i + width] + 1 : 0;
                packed[i] = (((long) rank[i] << 18) | second) << 17 | i;
            }
            Arrays.sort(packed);
            int classes = 0;
            for (int j = 0; j < size; j++) {
                if (j > 0 && (packed[j] >>> 17) != (packed[j - 1] >>> 17)) classes++;
                next[(int) (packed[j] & ((1 << 17) - 1))] = classes;
            }
            int[] t = rank; rank = next; next = t;
            if (classes == size - 1) break;
        }
        return rank;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        String a = st.nextToken(), b = st.nextToken();
        int length = a.length(), m = b.length();
        if (m < length) { System.out.println(-1); return; }
        // Sliding window over b: mismatches = letters whose counts differ from a.
        int[] difference = new int[26];
        for (int i = 0; i < length; i++) { difference[a.charAt(i) - 'a']++; difference[b.charAt(i) - 'a']--; }
        int mismatches = 0;
        for (int v : difference) if (v != 0) mismatches++;
        boolean[] valid = new boolean[m - length + 1];
        boolean any = false;
        for (int start = 0; start <= m - length; start++) {
            valid[start] = mismatches == 0;
            any |= valid[start];
            if (start + length < m) {
                int[][] moves = {{b.charAt(start) - 'a', 1}, {b.charAt(start + length) - 'a', -1}};
                for (int[] mv : moves) {
                    if (difference[mv[0]] != 0) mismatches--;
                    difference[mv[0]] += mv[1];
                    if (difference[mv[0]] != 0) mismatches++;
                }
            }
        }
        if (!any) { System.out.println(-1); return; }
        // Equal-length windows compare like their suffixes: take the valid start with the highest suffix rank.
        int[] rank = suffixRanks(b);
        int best = -1;
        for (int start = 0; start <= m - length; start++)
            if (valid[start] && (best < 0 || rank[start] > rank[best])) best = start;
        System.out.println(b.substring(best, best + length));
    }
}
